/** @var array<string,mixed> $attributes */ declare( strict_types=1 ); if( !defined( 'ABSPATH' ) ){exit;} $nextsaas_rows=nextsaas_items( $attributes, 'rows' ); $nextsaas_seats=max( 1, nextsaas_attr_int( $attributes, 'initialSeats', 10 ) ); $nextsaas_rate=nextsaas_attr_int( $attributes, 'teamMonthlyRate', 18 ); $nextsaas_total=$nextsaas_seats*$nextsaas_rate; $nextsaas_note=strtr( nextsaas_attr( $attributes, 'monthlyNoteTemplate' ), array( '{seats}'=>(string)$nextsaas_seats, '{currency}'=>nextsaas_attr( $attributes, 'currency', '$' ), '{rate}'=>(string)$nextsaas_rate, '{total}'=>(string)$nextsaas_total ) ); ?>
<section <?php echo nextsaas_section_attrs( 'pricing-compare', $attributes, array( 'section', 'ruled' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?> data-currency="<?php echo esc_attr( nextsaas_attr( $attributes, 'currency', '$' ) ); ?>" data-monthly-suffix="<?php echo esc_attr( nextsaas_attr( $attributes, 'monthlySuffix' ) ); ?>" data-yearly-suffix="<?php echo esc_attr( nextsaas_attr( $attributes, 'yearlySuffix' ) ); ?>" data-monthly-note="<?php echo esc_attr( nextsaas_attr( $attributes, 'monthlyNoteTemplate' ) ); ?>" data-yearly-note="<?php echo esc_attr( nextsaas_attr( $attributes, 'yearlyNoteTemplate' ) ); ?>" data-team-monthly="<?php echo esc_attr( (string)nextsaas_attr_int( $attributes, 'teamMonthlyRate', 18 ) ); ?>" data-team-yearly="<?php echo esc_attr( (string)nextsaas_attr_int( $attributes, 'teamYearlyRate', 15 ) ); ?>" data-business-monthly="<?php echo esc_attr( (string)nextsaas_attr_int( $attributes, 'businessMonthlyRate', 32 ) ); ?>" data-business-yearly="<?php echo esc_attr( (string)nextsaas_attr_int( $attributes, 'businessYearlyRate', 27 ) ); ?>"><div class="container"><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><h2 style="margin-bottom:40px" data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><div class="compare-wrap" tabindex="0" role="region" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'regionLabel' ) ); ?>"><table class="ds-table"><caption class="sr-only"><?php echo esc_html( nextsaas_attr( $attributes, 'caption' ) ); ?></caption><thead><tr><th scope="col"><?php echo esc_html( nextsaas_attr( $attributes, 'featureHeading' ) ); ?></th><th scope="col"><?php echo esc_html( nextsaas_attr( $attributes, 'personalHeading' ) ); ?></th><th scope="col"><?php echo esc_html( nextsaas_attr( $attributes, 'teamHeading' ) ); ?></th><th scope="col"><?php echo esc_html( nextsaas_attr( $attributes, 'businessHeading' ) ); ?></th></tr></thead><tbody><?php foreach( $nextsaas_rows as $nextsaas_i=>$nextsaas_row ): ?><tr><th scope="row" data-nextsaas-rich="rows.<?php echo esc_attr( (string)$nextsaas_i ); ?>.heading"><?php echo nextsaas_rich( (string)( $nextsaas_row['heading']??'' ) ); ?></th><td><?php echo esc_html( (string)( $nextsaas_row['personal']??'' ) ); ?></td><td><?php echo esc_html( (string)( $nextsaas_row['team']??'' ) ); ?></td><td><?php echo esc_html( (string)( $nextsaas_row['business']??'' ) ); ?></td></tr><?php endforeach; ?></tbody></table></div><div class="estimator"><div><p class="eyebrow" data-nextsaas-rich="estimatorEyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'estimatorEyebrow' ) ); ?></p><h3 data-nextsaas-rich="estimatorHeading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'estimatorHeading' ) ); ?></h3><p class="subtle" style="margin-top:16px" data-nextsaas-rich="estimatorBody"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'estimatorBody' ) ); ?></p></div><div><div class="estimate-controls"><div class="field"><label for="estimate-plan"><?php echo esc_html( nextsaas_attr( $attributes, 'planLabel' ) ); ?></label><select class="input" id="estimate-plan"><option value="Team"><?php echo esc_html( nextsaas_attr( $attributes, 'teamPlanLabel' ) ); ?></option><option value="Business"><?php echo esc_html( nextsaas_attr( $attributes, 'businessPlanLabel' ) ); ?></option></select></div><div class="field"><label for="estimate-seats"><?php echo esc_html( nextsaas_attr( $attributes, 'peopleLabel' ) ); ?></label><input class="input" id="estimate-seats" type="number" min="1" max="10000" step="1" value="<?php echo esc_attr( (string)$nextsaas_seats ); ?>"></div></div><div class="estimate-total" id="estimate-total" role="status" aria-live="polite"><?php echo esc_html( nextsaas_attr( $attributes, 'currency', '$' ) . $nextsaas_total . nextsaas_attr( $attributes, 'monthlySuffix' ) ); ?></div><p class="note" id="estimate-note" role="status"><?php echo esc_html( $nextsaas_note ); ?></p></div></div></div></section>
